[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>DeployCloud Blog — Discover the latest in web development</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;450;500;600;700;800;900&display=swap" rel="stylesheet" />
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --color-bg: #FAFAFA;
      --color-surface: #FFFFFF;
      --color-border: #E5E5E5;
      --color-border-light: #F0F0F0;
      --color-text-primary: #171717;
      --color-text-secondary: #525252;
      --color-text-muted: #737373;
      --color-accent: #0072F5;
      --color-accent-hover: #0060D1;
      --color-accent-light: #EFF6FF;
      --color-tag-bg: #F4F4F5;
      --color-tag-text: #3F3F46;
      --shadow-sm: 0 1px 2px 0 rgb(0 0 0 / 0.04);
      --shadow-md: 0 4px 16px 0 rgb(0 0 0 / 0.07), 0 1px 3px 0 rgb(0 0 0 / 0.04);
      --shadow-lg: 0 8px 32px 0 rgb(0 0 0 / 0.10), 0 2px 8px 0 rgb(0 0 0 / 0.06);
      --radius-sm: 6px;
      --radius-md: 10px;
      --radius-lg: 14px;
      --radius-full: 9999px;
      --font: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
    }

    html { scroll-behavior: smooth; }
    body {
      font-family: var(--font);
      background: var(--color-bg);
      color: var(--color-text-primary);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
      -moz-osx-font-smoothing: grayscale;
    }

    a { color: inherit; text-decoration: none; }
    button { font-family: inherit; cursor: pointer; border: none; background: none; }
    img { display: block; max-width: 100%; }
    ul, ol { list-style: none; }

    /* ──── LAYOUT ──── */
    .container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }
    .container--wide { max-width: 1340px; margin: 0 auto; padding: 0 24px; }

    /* ──── HEADER ──── */
    .header {
      position: sticky; top: 0; z-index: 100;
      background: rgba(250,250,250,0.92);
      backdrop-filter: blur(12px);
      -webkit-backdrop-filter: blur(12px);
      border-bottom: 1px solid var(--color-border);
    }
    .header__inner {
      display: flex; align-items: center; gap: 8px;
      height: 60px;
      max-width: 1340px; margin: 0 auto; padding: 0 24px;
    }
    .header__logo {
      display: flex; align-items: center; gap: 8px;
      font-size: 16px; font-weight: 700; letter-spacing: -0.02em;
      color: var(--color-text-primary);
      margin-right: 8px; flex-shrink: 0;
    }
    .header__logo-icon {
      width: 28px; height: 28px;
      background: var(--color-text-primary);
      border-radius: 7px;
      display: flex; align-items: center; justify-content: center;
    }
    .header__logo-icon svg { color: white; }
    .header__nav { display: flex; align-items: center; gap: 2px; flex: 1; }
    .nav-item { position: relative; }
    .nav-link {
      display: flex; align-items: center; gap: 4px;
      padding: 6px 11px; border-radius: var(--radius-sm);
      font-size: 14px; font-weight: 500; color: var(--color-text-secondary);
      transition: color 0.15s, background 0.15s;
      white-space: nowrap;
    }
    .nav-link:hover { color: var(--color-text-primary); background: var(--color-border-light); }
    .nav-link svg { transition: transform 0.2s; flex-shrink: 0; }
    .nav-item:hover .nav-link svg { transform: rotate(180deg); }
    .header__actions { display: flex; align-items: center; gap: 8px; margin-left: auto; }
    .btn-ghost {
      padding: 6px 14px; border-radius: var(--radius-sm);
      font-size: 14px; font-weight: 500; color: var(--color-text-secondary);
      transition: color 0.15s, background 0.15s;
    }
    .btn-ghost:hover { color: var(--color-text-primary); background: var(--color-border-light); }
    .btn-primary {
      padding: 6px 14px; border-radius: var(--radius-sm);
      background: var(--color-text-primary); color: #fff;
      font-size: 14px; font-weight: 600;
      transition: background 0.15s, opacity 0.15s;
    }
    .btn-primary:hover { background: #333; }

    /* Mega menu */
    .dropdown {
      position: absolute; top: calc(100% + 8px); left: 0;
      background: var(--color-surface);
      border: 1px solid var(--color-border);
      border-radius: var(--radius-lg);
      box-shadow: var(--shadow-lg);
      opacity: 0; visibility: hidden; pointer-events: none;
      transform: translateY(-6px);
      transition: opacity 0.18s, transform 0.18s, visibility 0.18s;
      z-index: 200;
    }
    .nav-item:hover .dropdown,
    .nav-item:focus-within .dropdown {
      opacity: 1; visibility: visible; pointer-events: auto; transform: translateY(0);
    }
    .dropdown--mega { width: 680px; padding: 24px; }
    .dropdown--resources { width: 360px; padding: 20px; }
    .dropdown__grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 0 24px; }
    .dropdown__section-title {
      font-size: 11px; font-weight: 700; text-transform: uppercase;
      letter-spacing: 0.07em; color: var(--color-text-muted);
      margin-bottom: 10px; padding-bottom: 6px;
      border-bottom: 1px solid var(--color-border-light);
    }
    .dropdown__item {
      display: block; padding: 7px 8px; border-radius: var(--radius-sm);
      transition: background 0.12s;
    }
    .dropdown__item:hover { background: var(--color-accent-light); }
    .dropdown__item-name { font-size: 13.5px; font-weight: 500; color: var(--color-text-primary); }
    .dropdown__item-desc { font-size: 12px; color: var(--color-text-muted); margin-top: 1px; line-height: 1.4; }
    .dropdown__cols { display: grid; grid-template-columns: repeat(3, 1fr); gap: 0 16px; }

    /* ──── BLOG HEADER ──── */
    .blog-hero {
      border-bottom: 1px solid var(--color-border);
      background: var(--color-surface);
    }
    .blog-hero__inner {
      max-width: 1340px; margin: 0 auto; padding: 48px 24px 0;
    }
    .blog-hero__label {
      display: inline-flex; align-items: center; gap: 6px;
      font-size: 12px; font-weight: 600; text-transform: uppercase;
      letter-spacing: 0.08em; color: var(--color-accent);
      margin-bottom: 12px;
    }
    .blog-hero__label::before {
      content: ''; display: block; width: 20px; height: 2px; background: var(--color-accent);
    }
    .blog-hero__title {
      font-size: clamp(28px, 4vw, 42px); font-weight: 800;
      letter-spacing: -0.03em; line-height: 1.15;
      color: var(--color-text-primary);
      max-width: 600px;
    }

    /* ──── FILTER BAR ──── */
    .filter-bar {
      background: var(--color-surface);
      border-bottom: 1px solid var(--color-border);
      position: sticky; top: 60px; z-index: 90;
    }
    .filter-bar__inner {
      max-width: 1340px; margin: 0 auto;
      padding: 0 24px;
      display: flex; align-items: center; gap: 12px;
      height: 56px; overflow-x: auto;
      scrollbar-width: none;
    }
    .filter-bar__inner::-webkit-scrollbar { display: none; }
    .filter-pills { display: flex; gap: 6px; flex-shrink: 0; }
    .pill {
      padding: 5px 14px; border-radius: var(--radius-full);
      font-size: 13.5px; font-weight: 500;
      border: 1px solid var(--color-border);
      color: var(--color-text-secondary);
      background: var(--color-surface);
      transition: all 0.15s; white-space: nowrap; cursor: pointer;
    }
    .pill:hover { border-color: var(--color-text-secondary); color: var(--color-text-primary); }
    .pill.active {
      background: var(--color-text-primary); color: #fff;
      border-color: var(--color-text-primary);
    }
    .filter-bar__search {
      margin-left: auto; flex-shrink: 0;
      display: flex; align-items: center; gap: 8px;
      background: var(--color-bg); border: 1px solid var(--color-border);
      border-radius: var(--radius-full); padding: 5px 14px;
      min-width: 200px;
    }
    .filter-bar__search svg { color: var(--color-text-muted); flex-shrink: 0; }
    .filter-bar__search input {
      border: none; background: none; outline: none;
      font-family: var(--font); font-size: 13.5px; color: var(--color-text-primary);
      width: 100%;
    }
    .filter-bar__search input::placeholder { color: var(--color-text-muted); }

    /* ──── FEATURED SECTION ──── */
    .section { padding: 48px 0; }
    .section--featured { background: var(--color-surface); padding: 48px 0; }
    .section__header { display: flex; align-items: baseline; justify-content: space-between; margin-bottom: 24px; }
    .section__label {
      font-size: 11px; font-weight: 700; text-transform: uppercase;
      letter-spacing: 0.08em; color: var(--color-text-muted);
    }

    .featured-grid {
      display: grid;
      grid-template-columns: 1.7fr 1fr;
      grid-template-rows: auto auto;
      gap: 1px;
      background: var(--color-border);
      border: 1px solid var(--color-border);
      border-radius: var(--radius-lg);
      overflow: hidden;
    }
    .featured-card {
      background: var(--color-surface);
      padding: 32px;
      display: flex; flex-direction: column;
      transition: background 0.15s;
      cursor: pointer;
    }
    .featured-card:hover { background: #FDFCFF; }
    .featured-card--main { grid-row: 1 / 3; }
    .featured-card--main .featured-card__title { font-size: clamp(20px, 2.2vw, 26px); }

    .featured-card__meta {
      display: flex; align-items: center; gap: 10px;
      margin-bottom: 16px;
    }
    .featured-card__tag {
      font-size: 11.5px; font-weight: 600; text-transform: uppercase;
      letter-spacing: 0.06em; color: var(--color-accent);
      background: var(--color-accent-light); border-radius: var(--radius-full);
      padding: 3px 10px;
    }
    .featured-card__date { font-size: 13px; color: var(--color-text-muted); }
    .featured-card__title {
      font-size: 20px; font-weight: 700; letter-spacing: -0.025em;
      line-height: 1.25; color: var(--color-text-primary);
      margin-bottom: 12px;
    }
    .featured-card__excerpt {
      font-size: 14.5px; color: var(--color-text-secondary);
      line-height: 1.65; flex: 1;
      display: -webkit-box; -webkit-line-clamp: 4; -webkit-box-orient: vertical; overflow: hidden;
    }
    .featured-card--main .featured-card__excerpt { -webkit-line-clamp: 6; }
    .featured-card__footer { margin-top: 20px; }
    .featured-card__author {
      display: flex; align-items: center; gap: 10px;
    }
    .avatar {
      width: 30px; height: 30px; border-radius: 50%;
      background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
      display: flex; align-items: center; justify-content: center;
      font-size: 11px; font-weight: 700; color: #fff; flex-shrink: 0;
    }
    .avatar--blue { background: linear-gradient(135deg, #0072F5 0%, #005AC4 100%); }
    .avatar--green { background: linear-gradient(135deg, #10b981 0%, #047857 100%); }
    .avatar--orange { background: linear-gradient(135deg, #f59e0b 0%, #d97706 100%); }
    .avatar--red { background: linear-gradient(135deg, #ef4444 0%, #b91c1c 100%); }
    .avatar--teal { background: linear-gradient(135deg, #14b8a6 0%, #0f766e 100%); }
    .avatar--purple { background: linear-gradient(135deg, #8b5cf6 0%, #6d28d9 100%); }
    .avatar--pink { background: linear-gradient(135deg, #ec4899 0%, #be185d 100%); }
    .author-name { font-size: 13px; font-weight: 500; color: var(--color-text-secondary); }
    .read-more {
      display: inline-flex; align-items: center; gap: 6px;
      font-size: 13.5px; font-weight: 600; color: var(--color-accent);
      margin-top: 16px; transition: gap 0.15s;
    }
    .read-more:hover { gap: 10px; }

    /* Stats strip inside featured card */
    .stats-strip {
      display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px;
      margin-top: 24px; padding-top: 20px;
      border-top: 1px solid var(--color-border-light);
    }
    .stat-item__value {
      font-size: 22px; font-weight: 800; letter-spacing: -0.03em;
      color: var(--color-text-primary);
    }
    .stat-item__value span { color: var(--color-accent); }
    .stat-item__label { font-size: 12px; color: var(--color-text-muted); line-height: 1.45; margin-top: 2px; }

    /* ──── LATEST NEWS ──── */
    .section--news { padding: 48px 0 64px; }
    .news-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 1px;
      background: var(--color-border);
      border: 1px solid var(--color-border);
      border-radius: var(--radius-lg);
      overflow: hidden;
    }
    .news-card {
      background: var(--color-surface);
      padding: 24px;
      display: flex; flex-direction: column;
      transition: background 0.15s;
      cursor: pointer;
    }
    .news-card:hover { background: #FDFCFF; }
    .news-card__tags { display: flex; gap: 6px; flex-wrap: wrap; margin-bottom: 12px; }
    .tag {
      font-size: 11.5px; font-weight: 600; text-transform: uppercase;
      letter-spacing: 0.06em; padding: 3px 9px; border-radius: var(--radius-full);
      background: var(--color-tag-bg); color: var(--color-tag-text);
    }
    .tag--engineering { background: #FEF3C7; color: #92400E; }
    .tag--customers { background: #D1FAE5; color: #065F46; }
    .tag--security { background: #FEE2E2; color: #991B1B; }
    .tag--community { background: #EDE9FE; color: #4C1D95; }
    .tag--company { background: #DBEAFE; color: #1E40AF; }
    .tag--v0 { background: #FCE7F3; color: #9D174D; }
    .tag--changelog { background: #F3F4F6; color: #374151; }
    .tag--press { background: #FEF9C3; color: #713F12; }
    .news-card__date { font-size: 12px; color: var(--color-text-muted); margin-bottom: 10px; }
    .news-card__title {
      font-size: 16px; font-weight: 700; letter-spacing: -0.02em;
      line-height: 1.3; color: var(--color-text-primary);
      margin-bottom: 8px;
    }
    .news-card:hover .news-card__title { color: var(--color-accent); }
    .news-card__excerpt {
      font-size: 13.5px; color: var(--color-text-secondary); line-height: 1.6;
      flex: 1;
      display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden;
    }
    .news-card__footer {
      margin-top: 16px; padding-top: 14px;
      border-top: 1px solid var(--color-border-light);
      display: flex; align-items: center; gap: 8px;
    }
    .news-card__author-name { font-size: 12.5px; font-weight: 500; color: var(--color-text-muted); }

    /* No results */
    .no-results {
      display: none;
      grid-column: 1 / -1;
      padding: 64px 24px; text-align: center;
      background: var(--color-surface);
    }
    .no-results.visible { display: flex; flex-direction: column; align-items: center; gap: 10px; }
    .no-results__icon { font-size: 36px; margin-bottom: 4px; }
    .no-results__title { font-size: 18px; font-weight: 700; color: var(--color-text-primary); }
    .no-results__desc { font-size: 14px; color: var(--color-text-muted); max-width: 380px; }

    /* Show more */
    .show-more-wrap { text-align: center; margin-top: 32px; }
    .btn-show-more {
      display: inline-flex; align-items: center; gap: 8px;
      padding: 10px 24px; border-radius: var(--radius-full);
      border: 1.5px solid var(--color-border);
      font-size: 14px; font-weight: 600; color: var(--color-text-secondary);
      background: var(--color-surface);
      transition: all 0.15s;
    }
    .btn-show-more:hover {
      border-color: var(--color-text-secondary);
      color: var(--color-text-primary);
      box-shadow: var(--shadow-sm);
    }
    .btn-show-more:disabled { opacity: 0.4; cursor: not-allowed; }

    /* ──── CTA BANNER ──── */
    .cta-section { padding: 64px 0; background: var(--color-surface); border-top: 1px solid var(--color-border); }
    .cta-grid {
      display: grid; grid-template-columns: 1fr 1fr; gap: 24px;
    }
    .cta-card {
      padding: 40px;
      border: 1px solid var(--color-border);
      border-radius: var(--radius-lg);
      background: var(--color-bg);
    }
    .cta-card--dark {
      background: var(--color-text-primary); color: #fff;
      border-color: var(--color-text-primary);
    }
    .cta-card__eyebrow {
      font-size: 11px; font-weight: 700; text-transform: uppercase;
      letter-spacing: 0.08em; color: var(--color-text-muted); margin-bottom: 12px;
    }
    .cta-card--dark .cta-card__eyebrow { color: rgba(255,255,255,0.5); }
    .cta-card__title {
      font-size: clamp(20px, 2.5vw, 28px); font-weight: 800;
      letter-spacing: -0.03em; line-height: 1.2;
      margin-bottom: 14px;
    }
    .cta-card__desc { font-size: 14.5px; color: var(--color-text-secondary); line-height: 1.6; margin-bottom: 24px; }
    .cta-card--dark .cta-card__desc { color: rgba(255,255,255,0.65); }
    .cta-actions { display: flex; gap: 10px; flex-wrap: wrap; }
    .btn-cta-primary {
      padding: 9px 20px; border-radius: var(--radius-sm);
      background: var(--color-accent); color: #fff;
      font-size: 14px; font-weight: 600;
      transition: background 0.15s;
    }
    .btn-cta-primary:hover { background: var(--color-accent-hover); }
    .btn-cta-secondary {
      padding: 9px 20px; border-radius: var(--radius-sm);
      border: 1.5px solid var(--color-border);
      font-size: 14px; font-weight: 600; color: var(--color-text-secondary);
      background: var(--color-surface);
      transition: all 0.15s;
    }
    .btn-cta-secondary:hover { border-color: var(--color-text-secondary); color: var(--color-text-primary); }
    .btn-cta-outline {
      padding: 9px 20px; border-radius: var(--radius-sm);
      border: 1.5px solid rgba(255,255,255,0.3);
      font-size: 14px; font-weight: 600; color: #fff;
      transition: border-color 0.15s, background 0.15s;
    }
    .btn-cta-outline:hover { border-color: rgba(255,255,255,0.7); background: rgba(255,255,255,0.07); }
    .pro-badge {
      display: inline-block; padding: 1px 7px; border-radius: 4px;
      background: rgba(255,255,255,0.15); font-size: 12px; font-weight: 700;
      vertical-align: middle; margin: 0 2px;
    }

    /* ──── FOOTER ──── */
    footer {
      background: var(--color-text-primary); color: rgba(255,255,255,0.75);
      padding: 64px 0 32px;
    }
    .footer-grid {
      display: grid;
      grid-template-columns: repeat(5, 1fr);
      gap: 32px 24px;
      margin-bottom: 48px;
    }
    .footer-col__title {
      font-size: 12px; font-weight: 700; text-transform: uppercase;
      letter-spacing: 0.07em; color: #fff; margin-bottom: 14px;
    }
    .footer-col__list { display: flex; flex-direction: column; gap: 8px; }
    .footer-col__link {
      font-size: 13.5px; color: rgba(255,255,255,0.55);
      transition: color 0.15s;
    }
    .footer-col__link:hover { color: #fff; }
    .footer-bottom {
      border-top: 1px solid rgba(255,255,255,0.1);
      padding-top: 24px;
      display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 12px;
    }
    .footer-bottom__logo { display: flex; align-items: center; gap: 8px; font-size: 15px; font-weight: 700; color: #fff; }
    .footer-bottom__logo-icon {
      width: 24px; height: 24px; background: #fff; border-radius: 5px;
      display: flex; align-items: center; justify-content: center;
    }
    .footer-bottom__logo-icon svg { color: var(--color-text-primary); }
    .footer-bottom__copy { font-size: 13px; color: rgba(255,255,255,0.4); }
    .status-badge {
      display: flex; align-items: center; gap: 6px;
      font-size: 12.5px; color: rgba(255,255,255,0.55);
    }
    .status-dot {
      width: 7px; height: 7px; border-radius: 50%; background: #22c55e;
      box-shadow: 0 0 0 2px rgba(34,197,94,0.25);
    }

    /* ──── RESPONSIVE ──── */
    @media (max-width: 1024px) {
      .featured-grid { grid-template-columns: 1fr; grid-template-rows: auto; }
      .featured-card--main { grid-row: auto; }
      .news-grid { grid-template-columns: repeat(2, 1fr); }
      .footer-grid { grid-template-columns: repeat(3, 1fr); }
      .cta-grid { grid-template-columns: 1fr; }
    }
    @media (max-width: 768px) {
      .header__nav { display: none; }
      .news-grid { grid-template-columns: 1fr; }
      .stats-strip { grid-template-columns: 1fr; gap: 12px; }
      .footer-grid { grid-template-columns: repeat(2, 1fr); }
      .blog-hero__inner { padding-top: 32px; }
      .section { padding: 32px 0; }
      .dropdown--mega { display: none; }
    }
    @media (max-width: 480px) {
      .footer-grid { grid-template-columns: 1fr 1fr; }
      .filter-bar__search { min-width: 140px; }
    }

    /* ──── UTILITIES ──── */
    .hidden { display: none !important; }
    .sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }
  </style>
</head>
<body>

<!-- ═══════════════════════════════ HEADER ═══════════════════════════════ -->
<header class="header" role="banner">
  <div class="header__inner">
    <!-- Logo -->
    <a href="/" class="header__logo" aria-label="DeployCloud home">
      <div class="header__logo-icon">
        <svg width="16" height="16" viewBox="0 0 16 16" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
          <path d="M8 2L14 5.5V10.5L8 14L2 10.5V5.5L8 2Z" fill="white"/>
